package com.smartresponse.api; import com.smartresponse.domain.*; import com.smartresponse.repository.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/emergencies/{id}/timeline") public class EmergencyTimelineController {private final EmergencyRepository emergencies;private final EmergencyUpdateRepository updates;private final UserRepository users;public EmergencyTimelineController(EmergencyRepository e,EmergencyUpdateRepository u,UserRepository a){emergencies=e;updates=u;users=a;}@GetMapping public List<EmergencyUpdate> list(@PathVariable UUID id){return updates.findByEmergencyIdOrderByCreatedAtAsc(id);}@PostMapping public void add(@PathVariable UUID id,Authentication a,@Valid @RequestBody EmergencyUpdateRequest r){updates.save(new EmergencyUpdate(emergencies.findById(id).orElseThrow(),users.findByEmailIgnoreCase(a.getName()).orElseThrow(),r.updateType(),r.message()));}}
